PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <https://w3id.org/runtime#>
SELECT DISTINCT ?zone ?zoneName ?tsid ?point ?pointClass WHERE {
  ?zone a brick:Zone .
  ?point a brick:AirTemperature .
  ?point brick:isPointOf ?zone .
  ?point ref:hasTimeseriesId ?tsid .
  OPTIONAL { ?zone rdfs:label ?zoneName }
}

