import csv, re

# Build catalog map: point_uri -> (timeseries_id, point_class, unit)
cat = {}
with open(CATALOG_CSV) as f:
    r = csv.DictReader(f)
    for row in r:
        cat[row['point_uri']] = row

# Find rows whose point_class relates to Air Temperature Sensor
ats = {uri:row for uri,row in cat.items() if 'Air' in row['point_class'] and 'Temperature' in row['point_class']}
print("num AT series", len(ats))
for k,v in list(ats.items())[:10]:
    print(k, v['timeseries_id'], v['point_class'])

